<template>
  <ProgressRoot
    v-bind="delegatedProps"
    :class="cn('relative h-3 w-full overflow-hidden rounded-full bg-accent border', props.class)"
  >
    <ProgressIndicator
      :class="cn('h-full w-full flex-1 bg-primary transition-all rounded-full', props.indicatorClass)"
      :style="`transform: translateX(-${100 - (props.modelValue ?? 0)}%);`"
    />
  </ProgressRoot>
</template>

<script setup lang="ts">
import { cn } from '@/components/ui/utils';
import { ProgressIndicator, ProgressRoot, type ProgressRootProps } from 'reka-ui';
import { computed, type HTMLAttributes } from 'vue';

const props = withDefaults(
  defineProps<ProgressRootProps & { class?: HTMLAttributes['class']; indicatorClass?: HTMLAttributes['class'] }>(),
  {
    modelValue: 0,
    class: undefined,
    indicatorClass: undefined,
  }
);

const delegatedProps = computed(() => {
  const { class: _, ...delegated } = props;

  return delegated;
});
</script>
